from __future__ import annotations

import ast
import re
import subprocess
from collections import Counter, defaultdict
from datetime import datetime
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "文档" / "01_仓库文件盘点_20260730.md"

HISTORICAL_DOCS = {
    "AI_Quant_Researcher_重构方案_v1.md",
    "BEARER_TOKEN_AUTH_SUMMARY.md",
    "CONSULTANT_ALPHA_SHADOW_RUN.md",
    "CONSULTANT_ALPHA_VNEXT_AUDIT.md",
    "CONSULTANT_ALPHA_VNEXT_IMPLEMENTATION.md",
    "CONSULTANT_ALPHA_VNEXT_REVIEW.md",
    "deep-research-report.md",
    "FINAL_STATUS_REPORT.md",
    "SOLUTION_COMPLETE.md",
    "SUCCESS_FINAL_REPORT.md",
    "TOKEN_REFRESH_GUIDE.md",
}

LEGACY_SCRIPTS = {
    "_patch_alpha_pipeline.py",
    "_tmp_chk.py",
    "Generated File May 18, 2026 - 6_52PM.py",
    "optimize_script.py",
    "test_auth_status.py",
    "test_batch_60.py",
    "test_catalog_issue.py",
    "test_cycle_script.py",
    "test_dump_profile_cookies.py",
    "test_fix_and_restart.py",
    "test_generator_direct.py",
    "test_generator_simple.py",
    "test_orchestrator_flow.py",
    "test_reauth.py",
    "test_simulate_with_env.py",
    "test_wq_auth.py",
}

PROTECTED = {
    "run_pipeline_loop.py",
    "run_pipeline_cycle.py",
    "auto_alpha_pipeline_rebuilt_v50.py",
}


def git_files() -> list[str]:
    raw = subprocess.check_output(["git", "ls-files", "-z"], cwd=ROOT)
    return [item.decode("utf-8") for item in raw.split(b"\0") if item]


def read_python(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return ""


def module_name(path: str) -> str:
    value = path[:-3].replace("/", ".")
    return value[:-9] if value.endswith(".__init__") else value


def is_runtime(path: str) -> bool:
    low = path.lower()
    name = Path(path).name.lower()
    if low.startswith(".wq_browser_profile/"):
        return True
    if any(part in low for part in ("/__pycache__/", "/.pytest_cache/")):
        return True
    if Path(name).suffix in {".log", ".sqlite", ".sqlite3", ".db", ".csv"}:
        return True
    if name in {
        "alpha_state.json",
        "pipeline_loop_blocked.flag",
        ".alpha_operators_cache.json",
    }:
        return True
    if re.fullmatch(r"pipeline_.*_state\.json", name):
        return True
    return name.startswith(("alpha_feedback_", "shadow_run_")) and name.endswith(".json")


def has_sensitive_risk(path: str) -> bool:
    low = path.lower()
    name = Path(path).name.lower()
    return (
        low.startswith(".wq_browser_profile/")
        or any(word in low for word in ("cookie", "session", "quarantine"))
        or name == ".env"
        or name.endswith((".pem", ".key"))
    )


def file_type(path: str) -> str:
    low = path.lower()
    if low.startswith(".wq_browser_profile/"):
        return "浏览器运行数据"
    suffix = Path(path).suffix.lower()
    return {
        ".py": "Python 源码",
        ".md": "Markdown 文档",
        ".csv": "CSV 数据",
        ".json": "JSON 配置/数据",
        ".yaml": "YAML 配置",
        ".yml": "YAML 配置",
        ".log": "日志",
        ".sqlite": "SQLite 数据库",
        ".sqlite3": "SQLite 数据库",
        ".db": "数据库/缓存",
        ".ps1": "PowerShell 脚本",
    }.get(suffix, "其他文件")


def action_for(path: str) -> tuple[str, str, str]:
    name = Path(path).name
    if is_runtime(path):
        return (
            "取消 Git 跟踪",
            "运行产物或本机会话数据，不应进入版本库。",
            "git check-ignore -q -- <path>；git ls-files --error-unmatch -- <path> 应失败",
        )
    if name in HISTORICAL_DOCS and "/" not in path:
        return (
            "移动",
            "历史审计、Shadow Run 或阶段性报告，非当前实现事实来源。",
            "移动后运行完整 pytest，并检查文档内引用",
        )
    if name in LEGACY_SCRIPTS and "/" not in path:
        return (
            "归档观察",
            "无核心/测试引用的临时、旧版或手工诊断脚本；连续两阶段观察后方可删除。",
            "移动后运行完整 pytest 与旧入口 --help",
        )
    if path in PROTECTED or path.startswith(("alpha_mining/", "tests/", ".agents/", ".claude/", ".cursor/")):
        return ("保留", "当前源码、测试、规则或受保护入口。", "pytest/入口测试或静态引用检查")
    if name in {"AGENTS.md", "CLAUDE.md", "README.md", ".gitignore", ".env.example"} or path.startswith(".superpowers/"):
        return ("保留", "项目配置、规则或获批任务资料。", "人工审阅并运行项目验证")
    if "/" not in path and Path(path).suffix.lower() in {".py", ".ps1"}:
        return ("未知待确认", "未发现确定引用，但可能是用户手工运维入口。", "两阶段引用观察和用户确认")
    return ("保留", "未发现运行产物或敏感数据特征。", "静态引用检查与项目测试")


def main() -> None:
    tracked = git_files()
    py_paths = [path for path in tracked if path.endswith(".py") and (ROOT / path).is_file()]
    texts = {path: read_python(ROOT / path) for path in py_paths}
    imported_by: dict[str, set[str]] = defaultdict(set)
    test_refs: dict[str, set[str]] = defaultdict(set)
    dynamic_refs: dict[str, set[str]] = defaultdict(set)
    cli_refs: dict[str, set[str]] = defaultdict(set)

    modules = {module_name(path): path for path in py_paths}
    basenames = defaultdict(list)
    for path in tracked:
        basenames[Path(path).name].append(path)

    for source, text in texts.items():
        try:
            tree = ast.parse(text, filename=source)
        except SyntaxError:
            tree = None
        if tree is not None:
            for node in ast.walk(tree):
                names: list[str] = []
                if isinstance(node, ast.Import):
                    names = [alias.name for alias in node.names]
                elif isinstance(node, ast.ImportFrom) and node.module:
                    names = [node.module]
                for name in names:
                    for module, target in modules.items():
                        if name == module or name.startswith(module + "."):
                            imported_by[target].add(source)
        for name, targets in basenames.items():
            if name and name in text:
                for target in targets:
                    if source.startswith("tests/"):
                        test_refs[target].add(source)
                    if re.search(r"(?:importlib|__import__|runpy|SourceFileLoader|spec_from_file_location)", text):
                        dynamic_refs[target].add(source)
                    if re.search(r"(?:subprocess|Popen|check_call|check_output|python|py -3)", text):
                        cli_refs[target].add(source)

    rows: list[str] = []
    actions: Counter[str] = Counter()
    total_size = 0
    for path in tracked:
        full = ROOT / path
        try:
            stat = full.stat()
            size = stat.st_size
            modified = datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds")
        except OSError:
            size = -1
            modified = "文件缺失"
        total_size += max(size, 0)
        action, reason, verify = action_for(path)
        actions[action] += 1
        imported = "是" if imported_by[path] else "否"
        cli = "是" if cli_refs[path] or (path.endswith(".py") and "__main__" in texts.get(path, "")) else "否"
        tested = "是" if test_refs[path] or path.startswith("tests/") else "否"
        dynamic = "是" if dynamic_refs[path] else "否"
        runtime = "是" if is_runtime(path) else "否"
        sensitive = "高" if has_sensitive_risk(path) else "低"
        safe_path = path.replace("|", "\\|")
        rows.append(
            f"| `{safe_path}` | {file_type(path)} | {size} | {modified} | {imported} | {cli} | {tested} | {dynamic} | {runtime} | {sensitive} | {action} | {reason} | {verify} |"
        )

    summary = "\n".join(f"- {key}: {value}" for key, value in sorted(actions.items()))
    document = f"""# 仓库文件盘点（2026-07-30）

## 结论

- 基线 SHA：`3c7b20a53d6e14e7170a06ef28372cf0229356aa`
- 分支：`main`
- 已跟踪文件：{len(tracked)}
- 已跟踪文件总大小：{total_size} bytes
